SELECT AVG(gcs_total) AS average_gcs_total FROM (SELECT icustays.subject_id, icustays.hadm_id, chartevents.charttime, chartevents.value, chartevents.valuenum, chartevents.valueuom, gcs_total FROM icustays JOIN chartevents ON icustays.hadm_id = chartevents.hadm_id AND icustays.subject_id = chartevents.subject_id JOIN patients ON icustays.subject_id = patients.subject_id WHERE patients.gender = 'M' AND patients.anchor_age = 82 AND patients.anchor_year BETWEEN 77 AND 87 AND chartevents.itemid = 170290007) AS subquery;